// Pega todos os itens que chegaram (30 itens)
const allItems = $input.all();

// Se não houver itens, interrompe
if (allItems.length === 0) {
  return [];
}

// Cria um Map para armazenar os itens únicos, usando o número da linha como chave
const uniqueMap = new Map();

allItems.forEach(item => {
  const rowNumber = item.json._row_number; // campo adicionado pelo Get Rows
  if (!uniqueMap.has(rowNumber)) {
    uniqueMap.set(rowNumber, item);
  }
});

// Converte o Map de volta para um array de itens
const uniqueItems = Array.from(uniqueMap.values());

// Retorna os itens únicos (agora apenas 3)
return uniqueItems;
